// example: single-context stream with whole-call timeout
ctx, cancel := context.WithTimeout(context.Background(), 45*time.Second)
defer cancel()
sess, err := client.NewStream(ctx, &StreamOpts{Model: "rwd-infer-1"})
if err != nil { return err }
defer sess.Close()
for {
  chunk, err := sess.Recv(ctx)
  if err != nil {
    if errors.Is(err, context.Canceled) { log.Println("client canceled"); break }
    if errors.Is(err, context.DeadlineExceeded) { log.Println("deadline"); break }
    return err
  }
  process(chunk)
}
// example: per-chunk short deadline for snappy UI
baseCtx := context.Background()
sess, _ := client.NewStream(baseCtx, nil)
for {
  perChunkCtx, cancel := context.WithTimeout(baseCtx, 400*time.Millisecond)
  chunk, err := sess.Recv(perChunkCtx)
  cancel()
  if err != nil {
    if errors.Is(err, context.DeadlineExceeded) {
      // treat as transient: continue to next chunk or optionally close
      continue
    }
    return err
  }
  render(chunk)
}
// example: deterministic shutdown (signal handling)
ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt)
defer cancel()
stream, _ := client.NewStream(ctx, nil)
go func() {
  <-ctx.Done()
  stream.Close() // triggers Recv to return promptly
}()
for {
  c, err := stream.Recv(ctx)
  if err != nil { break }
  // ...
}
